// Стили генерируемой страницы. В итоговый HTML попадают только фрагменты выбранной концепции:
// токены проекта, навигация, hero и варианты блоков — поэтому страницы разных архитектур
// отличаются композицией, а не только значениями переменных.

export function tokensCss(vs) {
  const p = vs.palette, t = vs.typography, s = vs.shape;
  const space = { compact: 'clamp(44px, 6vw, 84px)', regular: 'clamp(56px, 8vw, 112px)', airy: 'clamp(60px, 9vw, 124px)' }[vs.layout.rhythm];
  const vw = Math.round((t.h1max - 1) * 1.25 * 100) / 100;
  const h2max = Math.round(Math.min(Math.max(t.h1max * 0.55, 1.7), 2.9) * 100) / 100;
  return `:root{color-scheme:${p.mode};--ds-bg:${p.bg};--ds-surface:${p.surface};--ds-text:${p.text};--ds-text-muted:${p.muted};--ds-border:${p.border};--ds-accent:${p.accent};--ds-accent-contrast:${p.accentText};--ds-focus:${p.focus};--ds-container:${vs.layout.container}px;--ds-section-space:${space};--ds-radius-sm:${s.sm};--ds-radius-md:${s.md};--ds-radius-lg:${s.lg};--ds-radius-pill:${s.button};--ds-font-body:${t.body};--ds-font-display:${t.display};${t.accent ? `--ds-font-accent:${t.accent};` : ""}--u-accent-ink:${p.accentInk};--u-tint:${p.tint};--u-dw:${t.weight};--u-dt:${t.tracking};--u-dc:${t.transform};--u-h1:clamp(${t.h1min}rem, calc(1rem + ${vw}vw), ${t.h1max}rem);--u-h2:clamp(1.45rem, calc(1rem + 1.9vw), ${h2max}rem);--u-h3:clamp(1.08rem, calc(1rem + .35vw), 1.3rem)}`;
}

